            self.platform_name = PLATFORM_NAMES.get(kwargs["sat_id"], kwargs["sat_id"])
        except KeyError:
            # NWCSAF/PPS
            self.platform_name = kwargs["platform_name"]
            self.pps = True

        self.sensor = set([SENSOR.get(self.platform_name, "seviri")])

